      "notas": "El hort ha patit prou de Texas, falta de color generalitzada en tot el hort, les puntes en un estat més  crític perquè  no sé  están  regant. Gran problema de la campanya no les gomes tallades que el mal era molt menor del esperat, sino tot taponat de fang. Algun arbre aleatori pareix que se estiga morint. Hi ha fruta però no acaba de agafar calibre. la brossano se acaba de morir del tot. Totes les carxofes están obertes avore si se queda més  limpio, tancar-les  demà.  Esta vesprada revisar el reg instalat i fer un forat per empalmar la goma que falta (garrafa verda). Tal volta la mala cara dels arbres i perquè  no acaben de despegar  és  una gran  incidencia de PRC i serpeta. Ara esta prou morta però  ha hagut molta causan seca de rames per dins del arbres. Destarugar rames grans i pintar talls. Hort prou be. Teronges bon calibre, y en menos cotonet que any pasat. Heu fet fet mol bona faena."
