      "hierba": "Limpio",
      "notas": "Ha pegat una ultima brota que pareix bona i també  hi ha més  fruta del que pensàvem. Tot I això, hi ha que destarugar ja amb motoserra gran i pintar talls si no la faena es repetitiva e inutil. Contra el veí la doble tira que no es tracta te una defoliació  terrible, MB i cotonet, acapolar tira ja. Hory bona trasa salvo mal de trips. Bon color y bona fruta, pero poques.  Despues de cullir llevar tira vora y podar mosatros"
