      "notas": "Balcó: Hort en bona cara, bon color i  bona brotada, és  veu prou fruta. Tot i que hi han mals de AR en fruta, no trobe viva. Hi ha seca de rames. L'hort és  sorpresa cada volta que passa aigua per la sèquia  de damunt  eixa és la raó per la que han mort els arbres contra la punta. Com podríem solventarlo? Acapolar soques de arbres morts. No se ha fet encara la brossa. Hípica: El hort te molt bona cara i una nova brotació  prou bona. Hi ha fruta amb algo de mal de AR en algun punt però  molt poc. AR soles en algun marge. Se te que fer la brossa encara no feta. Acapolar soques. Poca presència  de plagues."
