      "hierba": "Limpio",
      "notas": "Gran:  En general, el huerto se ve mucho mejor. Hay un montón de brotaciones muy buenas . Hay alguna hoja que se ha quedado un poco corta de color. El final de las brotaciones está afectado de trip . Ya no he visto nada de araña viva. Solo algunas colonias se enoja. En el sitio donde vi araña la semana pasada lo he visto limpio . Sí, que parece que las gomas hayan hecho efecto y esos árboles hayan mejorado un poco de cara. Respecto a los que no se ha cambiado la tubería . Sigue cayendo alguna hoja y alguna fruta. Plantons: El final de los brotes está afectado de trip . Pero en general se ven muy muy buenos puntos. Tienen hojas gigantescas, pero se han quedado enrolladas . Están limpios de todas plagas, no hay ni araña ni mosca blanca ."
