      "notas": "Balcó: Hort en molt bona cara, fulla oscura i nova brotació. Encara hi ha seca de rames I fulles tocades de AR, però  no trobe AR viva ni en fruta. Fer la brossa ja manat i acapolar arbres seques. Llevar cremaor. És  veu molt a fruta  I bon calibre. Hípica: Hort amb molt bona cara, encara que perd un poc de tonalitat de verd, tot I això  molt bona brotació. Encara és  veu algo de mal de AR en fulla I defoliació, però  AR  viva soles en punts molt específics on no es pot tractar. És  veu fruta. Brossa per a fer-se ja manada. Llevar tocons I araujes especialment contra els cavalls."
