      "hierba": "Poca hierba",
      "notas": "Lane: Los árboles tienen Texas. Se deberían de tratar. También se ve algún árbol que ha tenido araña roja . Hay árboles que parece que les haya sentado mal algún tratamiento, como si tuvieran un problema hormonal o con el herbicida. Se ve algo de fruta . Se ve también algo de fruta pequeña . Hay q quitar araujas. Chislet XLO: Las plantas están muy poco brotadas. No sé si merece la pena poner el exhire . Los XL o están críticos. Tienen muy muy mala cara. En general han tenido un montón de daño de araña . Hay algún plantón que no sé si riega bien? Habría que revisar riego?. XLO ort: No sé fruta . Los árboles no tienen tan mala cara como en el cheslet . Hay algún árbol más que está brotado. Aún así, los árboles en general siguen sin tener buena cara. No veo araña viva . No veo daños de araña viva ."
