      "notas": "Patos: Ha tenido muchos daños de araña roja , el tratamiento ha funcionado bien casi todos los adultos de araña roja están muertos. Se ven muy pocos y se ve alguna colonia . (tratar dentro de siete días?) Se ve alguna terroncha . Hay muchísimas araujas y muchísima hierba solucionar para la semana que viene. Orri: El hort hui no es veu millor. Se veu AR en alguns llocs."
