      "notas": "Banca grna: Árboles superbrotados. Se ve una barbaridad de daño de araña, no solo en hojas que todavía faltan muchas por caer, sino también se ve alguna fruta tocada . Hay presencia de araña en hoja pero muy baja. Se tendría que pasar . Apenas se ve fruta, ha caído muchísima.Se puede pensar en ya que hacemos el tratamiento meter algo para la brotación porque es hay mucha brotación. Plantons:Los plantones están espectaculares. Se ven bastante limpios de araña. Han brotado muchísimo y con unas hojas super gordas . Mirar de utilizar el producto de Brasinoesteroides. En todos los sitios . Se tienen que desarugar y dar un poco de forma."
