      "notas": "19 American Beauty, 2 Sugar Dragon, 2 G2, 16 Halley Comet , Polinizadas con Pink. Total 39. Año pasado 31. Comentario sobre polinizadores:\nLas variedades que tenemos catalogadas como Pink y Red son en todo iguales : aspecto exterior, color de pulpa, sabor, fecha de floracion y recoleccion y forma de la planta. Tambien son polinizadoras mediocres, pero no desastrosas. Si no hay otras opciones polinizo con ellas. Si hay poco polen de calidad mezclo su polen con el de JC1, G2, Hibridum... hasta un porcentaje aproximado del 50%. Con la Costa Rica hago lo mismo. Las Costa Rica, JC1 y G2 tienen brácteas más grandes, así que parecen más grandes de lo que son. Lo malo es que Hibridum no sabe a nada.  Ademes les hibridum tampoc son molt xules."
